Object.assign(SNIP,{"h09cong": "long long ucln(long long a, long long b) {\n    while (b != 0) { long long r = a % b; a = b; b = r; }\n    return a;\n}\n\nlong long bcnn(long long a, long long b) {\n    return a / ucln(a, b) * b;\n}\n\nlong long luyThua(long long a, long long b, long long m) {   // a^b mod m\n    long long kq = 1 % m;\n    a %= m;\n    while (b > 0) {\n        if (b & 1) kq = kq * a % m;\n        a = a * a % m;\n        b >>= 1;\n    }\n    return kq;\n}"});PRESET_NOTES["l9"]={"Ví dụ: Thuật toán Euclid từng bước": "252 = 2 · 105 + 42, 105 = 2 · 42 + 21, 42 = 2 · 21 + 0: gcd = 21. Hàm __gcd của g++ cho cùng kết quả.", "Ví dụ: Modulo với số âm": "a − b = −7 chia hết cho 7 nên ra 0. Với −8: C++ cho −8 % 7 = −1 (dấu theo số bị chia); công thức (x % m + m) % m đưa về 6. Tích hai số gần 10⁹ vẫn vừa long long.", "Ví dụ: Lũy thừa nhanh": "13 = 1101 (nhị phân) nên 3¹³ = 3⁸ · 3⁴ · 3¹. Bốn vòng lặp thay vì 13 phép nhân; với b = 10¹⁸ chỉ khoảng 60 vòng."};EX_HINTS["l9"]=[["Chia cả tử và mẫu cho gcd(a, b).", "Thử từng ước từ min(a, b) xuống là tới 10¹⁸ bước.", "Dùng __gcd hoặc tự viết Euclid với long long."], ["Nhân b lần là 10¹⁸ bước: không bao giờ xong.", "Lũy thừa nhanh: xét từng bit của b, bình phương a sau mỗi vòng.", "a có thể lớn hơn m: lấy a %= m trước. m = 1 thì đáp án luôn 0: kq = 1 % m."], ["Đáp án là bội chung nhỏ nhất của cả dãy, gộp dần.", "Code mẫu nhân trước: kq · t có thể vượt 10¹⁸ dù đáp án vừa long long (thử 10⁹ và 999 999 999).", "Viết kq / gcd(kq, t) · t."]];
