const PR9=[{label:"Ví dụ: Thuật toán Euclid từng bước",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    long long a = 252, b = 105;\n    while (b != 0) {\n        long long r = a % b;\n        cout << a << \" \" << b << \" -> du \" << r << \"\\n\";\n        a = b;\n        b = r;\n    }\n    cout << \"gcd = \" << a << \", __gcd = \" << __gcd(252LL, 105LL) << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["a","b","r"]}]},{label:"Ví dụ: Modulo với số âm",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    const long long M = 1000000007;\n    long long a = 3, b = 10;\n    cout << (a - b) % 7 << \"\\n\";                    // -7 chia hết cho 7\n    cout << (a - b - 1) % 7 << \" \" << ((a - b - 1) % 7 + 7) % 7 << \"\\n\";\n    long long x = 999999999, y = 999999999;\n    cout << x * y % M << \"\\n\";                       // < 10^18: vừa long long\n    return 0;\n}",viz:[{type:"vars",names:["a","b","x","y"]}]},{label:"Ví dụ: Lũy thừa nhanh",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    long long a = 3, b = 13, m = 1000, kq = 1;\n    a %= m;\n    while (b > 0) {\n        if (b & 1) kq = kq * a % m;     // bit thấp nhất của b bật\n        a = a * a % m;                  // a, a², a⁴, a⁸\n        b >>= 1;\n    }\n    cout << kq << \"\\n\";                 // 3^13 = 1594323\n    return 0;\n}",viz:[{type:"vars",names:["a","b","kq"]}]}];
